pub(crate) fn translation(key: &str, code: &str) -> Option<&'static str> {
    let entry = ENTRIES
        .binary_search_by(|entry| entry.0.cmp(key))
        .ok()
        .map(|index| &ENTRIES[index])?;
    entry
        .1
        .iter()
        .find(|(locale, _)| *locale == code)
        .map(|(_, value)| *value)
}
